package com.lenid.accountlab;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import org.json.*;
public final class AccountGate {
 static Context context;static boolean launchedVehicle=false,checkedOrigin=false;
 public static void init(Context c){context=c.getApplicationContext();if(!checkedOrigin){try{new LabHttp(context);checkedOrigin=true;}catch(Exception ignored){}}}
 static android.content.SharedPreferences prefs(){return context.getSharedPreferences("phone",0);}
 public static void save(Context c,JSONObject me)throws Exception{init(c);prefs().edit().putString("verified_profile",me.getJSONObject("profile").toString()).apply();}
 public static void clear(Context c){init(c);prefs().edit().remove("verified_profile").remove("access").remove("refresh").apply();}
 static void ensureContext(){if(context!=null)return;try{Object companion=Class.forName("com.zeekrlife.base.BaseApp").getField("Companion").get(null);init((Context)companion.getClass().getMethod("getApplication").invoke(companion));}catch(Exception ignored){}}
 public static boolean logged(){ensureContext();return context!=null&&!prefs().getString("access","").isEmpty()&&!prefs().getString("verified_profile","").isEmpty();}
 public static Object userInfo(){try{Class<?> cls=Class.forName("com.zeekrlife.data.entity.UserInfoEntity");Object obj=cls.getConstructor().newInstance();if(!logged())return obj;JSONObject p=new JSONObject(prefs().getString("verified_profile","{}"));for(String[] pair:new String[][]{{"accountId",p.getString("user_id")},{"accountInfoId",p.getString("user_id")},{"nickname",p.getString("display_name")},{"username",p.getString("display_name")}}){java.lang.reflect.Field f=cls.getDeclaredField(pair[0]);f.setAccessible(true);f.set(obj,pair[1]);}return obj;}catch(Exception e){return null;}}
 public static int visibleTab(int index){return index==1||index==3?2:index;}
 public static void hideTabs(Activity a){for(String name:new String[]{"tab_message","tab_mall"}){int id=a.getResources().getIdentifier(name,"id",a.getPackageName());View v=a.findViewById(id);if(v!=null){v.setVisibility(View.GONE);v.setEnabled(false);v.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);}}}
 static final java.util.WeakHashMap<Activity,Boolean> listeners=new java.util.WeakHashMap<>();
 static void menuRow(Activity a,String idName,String titleText,String section){int id=a.getResources().getIdentifier(idName,"id",a.getPackageName());View row=a.findViewById(id);if(row==null)return;int title=a.getResources().getIdentifier("tv_menu_type_name","id",a.getPackageName());TextView label=row.findViewById(title);if(label!=null&&!titleText.contentEquals(label.getText()))label.setText(titleText);row.setContentDescription(titleText);row.setEnabled(true);row.setOnClickListener(v->a.startActivity(new Intent(a,PhoneActivity.class).putExtra("section",section)));}
 static final java.util.WeakHashMap<ImageView,String> shownPhotos=new java.util.WeakHashMap<>();
 static View named(Activity a,String name){return a.findViewById(a.getResources().getIdentifier(name,"id",a.getPackageName()));}
 static void profileIdentity(Activity a){try{if(!logged())return;JSONObject profile=new JSONObject(prefs().getString("verified_profile","{}"));View holder=named(a,"name_label_wrap");if(holder!=null){TextView name=holder.findViewById(a.getResources().getIdentifier("tv_name","id",a.getPackageName()));String value=profile.optString("display_name","");if(name!=null&&!value.contentEquals(name.getText()))name.setText(value);}View avatar=named(a,"iv_headimg");if(avatar!=null){ImageView image=avatar.findViewById(a.getResources().getIdentifier("imgv_avatar","id",a.getPackageName()));String uri=prefs().getString("photo_uri","");if(image!=null&&!uri.equals(shownPhotos.get(image))){if(!uri.isEmpty())image.setImageURI(android.net.Uri.parse(uri));else image.setImageResource(android.R.drawable.ic_menu_myplaces);image.setContentDescription("Фото профиля");shownPhotos.put(image,uri);}avatar.setOnClickListener(v->a.startActivity(new Intent(a,PhoneActivity.class).putExtra("section","profile")));}}catch(Exception ignored){}}
 static void contrast(View v){if(v==null)return;if(android.os.Build.VERSION.SDK_INT>=29)v.setForceDarkAllowed(false);if(v instanceof TextView){TextView t=(TextView)v;if(t.getCurrentTextColor()!=0xff232a32)t.setTextColor(0xff232a32);}if(v instanceof ImageView){ImageView image=(ImageView)v;android.content.res.ColorStateList tint=android.content.res.ColorStateList.valueOf(0xff232a32);image.setImageTintList(tint);image.setColorFilter(0xff232a32,android.graphics.PorterDuff.Mode.SRC_IN);android.graphics.Paint paint=new android.graphics.Paint();paint.setColorFilter(new android.graphics.PorterDuffColorFilter(0xff232a32,android.graphics.PorterDuff.Mode.SRC_IN));image.setLayerType(View.LAYER_TYPE_HARDWARE,paint);try{image.getClass().getMethod("setSupportImageTintList",android.content.res.ColorStateList.class).invoke(image,tint);}catch(Exception ignored){}}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)contrast(g.getChildAt(i));}}
 static void vehicleHeader(Activity a){View title=named(a,"cl_title");if(title==null||!title.isShown())return;contrast(title);contrast(named(a,"im_msg"));contrast(named(a,"im_menu"));contrast(named(a,"ll_mileage"));contrast(named(a,"ll_update"));View decor=a.getWindow().getDecorView();if(android.os.Build.VERSION.SDK_INT>=30&&a.getWindow().getInsetsController()!=null)a.getWindow().getInsetsController().setSystemBarsAppearance(8,8);int flags=decor.getSystemUiVisibility();if((flags&View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR)==0)decor.setSystemUiVisibility(flags|View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);}
 static void accountRow(Activity a){vehicleHeader(a);profileIdentity(a);menuRow(a,"recommend_btn","Мой аккаунт","profile");menuRow(a,"tv_koc","Мои автомобили","vehicles");}

 public static void attach(Activity a){init(a);if(!logged()){a.startActivity(new Intent(a,PhoneActivity.class));return;}ReleaseUpdate.check(a);hideTabs(a);ViewGroup root=a.findViewById(android.R.id.content);if(root==null)return;if(!launchedVehicle){launchedVehicle=true;root.postDelayed(()->{View car=named(a,"tab_vehicle");if(car!=null)car.performClick();},300);}View old=root.findViewWithTag("local-account");if(old!=null&&old.getParent() instanceof ViewGroup)((ViewGroup)old.getParent()).removeView(old);accountRow(a);if(!listeners.containsKey(a)){listeners.put(a,true);root.getViewTreeObserver().addOnGlobalLayoutListener(()->accountRow(a));}}
}
